o=['ФОНЫ — ПРОМТЫ ДЛЯ VEO','','Настройки: Veo 3.1 (Flow), 9:16, 1080p, 8 с. Каждый блок — один промт, копируй целиком.','','']
for h,f,t in P:o+=[f'=== {h} → файл {f}.mp4 ===','',t+' '+TAIL,'','']
